Run it and confirm the cart itself is untouched:
```js
import assert from "node:assert/strict";
const cart = [
  { name: "tea", price: 4, qty: 2, inStock: true },
  { name: "mug", price: 9, qty: 1, inStock: false },
  { name: "jam", price: 6, qty: 3, inStock: true },
];
const lineCosts = cart.filter((item) => item.inStock).map((item) => item.price * item.qty);
assert.deepEqual(lineCosts, [8, 18]);
const total = lineCosts.reduce((sum, cost) => sum + cost, 0);
assert.equal(total, 26);
assert.equal(cart.length, 3);
assert.equal([].reduce((sum, cost) => sum + cost, 0), 0); // initial value makes empty input safe
console.log(total);
```
